{
  "packet_id": "H6-T04-2",
  "claim_id": "C036",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C036.main",
    "value": "A documentary gap does not initially justify attributing a failure to the customer.",
    "scope": "Initial interpretation of a gap, without additional clarification or evidence.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly limits the initial inference from a gap to clarification or better recording and excludes attributing customer failure."
    }
  },
  "signal_basis": {
    "component_id": "C036.signal_basis",
    "value": "Inspection of account histories identifies missing links or contradictions as breaks in documented continuity and seeks participant clarification while preserving the original record.",
    "scope": "Initial assessment of unexplained transitions or gaps in the tracked histories.",
    "provenance": {
      "refs": [
        {
          "source_id": "P005",
          "role": "SUPPORT"
        },
        {
          "source_id": "P013",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply both the inspection and clarification operation and the interpretation of missing links or contradictions as documentary breaks."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C036.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is required for this supported limitation on inference."
    }
  },
  "rationale": "A gap establishes an inadequacy in the documented history, without distinguishing incomplete recording from customer conduct. It therefore does not, by itself, license initial attribution of customer failure. The claim preserves that distinction within its explicit limits.",
  "uncertainty": "The customer's actual conduct remains unresolved; the claim does not assert that no failure occurred.",
  "anomalies": []
}
